ALTER TABLE `sites` ADD COLUMN `publishStatus` enum('draft','published','unpublished') NOT NULL DEFAULT 'draft';
ALTER TABLE `sites` ADD COLUMN `publishedAt` timestamp NULL;
ALTER TABLE `sites` ADD COLUMN `lastPublishedVersion` int NOT NULL DEFAULT 0;
ALTER TABLE `sites` ADD COLUMN `draftContent` json NOT NULL;
ALTER TABLE `sites` ADD COLUMN `publishedContent` json NOT NULL;
ALTER TABLE `sites` ADD COLUMN `deletedAt` timestamp NULL;
ALTER TABLE `messages` ADD COLUMN `status` enum('new','contacted','qualified','won','lost') NOT NULL DEFAULT 'new';
ALTER TABLE `messages` ADD COLUMN `source` varchar(100) DEFAULT 'website';
ALTER TABLE `messages` ADD COLUMN `notes` text NULL;
ALTER TABLE `messages` ADD COLUMN `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
CREATE TABLE IF NOT EXISTS `site_versions` (`id` int AUTO_INCREMENT PRIMARY KEY, `siteId` int NOT NULL, `version` int NOT NULL, `content` json NOT NULL, `createdBy` int NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY `site_versions_site_version_uq` (`siteId`,`version`), KEY `site_versions_site_idx` (`siteId`));
CREATE TABLE IF NOT EXISTS `site_visits` (`id` int AUTO_INCREMENT PRIMARY KEY, `siteId` int NOT NULL, `sessionHash` varchar(128), `path` varchar(500) NOT NULL DEFAULT '/', `referrer` varchar(1000), `device` varchar(32), `browser` varchar(64), `country` varchar(2), `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY `site_visits_site_date_idx` (`siteId`,`createdAt`));
CREATE TABLE IF NOT EXISTS `analytics_daily` (`id` int AUTO_INCREMENT PRIMARY KEY, `siteId` int NOT NULL, `day` varchar(10) NOT NULL, `pageViews` int NOT NULL DEFAULT 0, `uniqueVisitors` int NOT NULL DEFAULT 0, `leads` int NOT NULL DEFAULT 0, UNIQUE KEY `analytics_daily_site_day_uq` (`siteId`,`day`));
CREATE TABLE IF NOT EXISTS `domains` (`id` int AUTO_INCREMENT PRIMARY KEY, `siteId` int NOT NULL, `hostname` varchar(255) NOT NULL UNIQUE, `verificationToken` varchar(128) NOT NULL, `status` enum('pending','verified','active','failed') NOT NULL DEFAULT 'pending', `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `verifiedAt` timestamp NULL);
CREATE TABLE IF NOT EXISTS `plans` (`id` int AUTO_INCREMENT PRIMARY KEY, `key` varchar(32) NOT NULL UNIQUE, `name` varchar(100) NOT NULL, `siteLimit` int NOT NULL, `storageLimitMb` int NOT NULL, `aiLimit` int NOT NULL, `analyticsRetentionDays` int NOT NULL, `customDomain` boolean NOT NULL DEFAULT false, `active` boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS `subscriptions` (`id` int AUTO_INCREMENT PRIMARY KEY, `userId` int NOT NULL, `planId` int NOT NULL, `provider` varchar(50), `providerSubscriptionId` varchar(255), `status` enum('trialing','active','past_due','canceled','incomplete') NOT NULL DEFAULT 'active', `currentPeriodEnd` timestamp NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `payments` (`id` int AUTO_INCREMENT PRIMARY KEY, `userId` int NOT NULL, `subscriptionId` int NULL, `provider` varchar(50), `providerPaymentId` varchar(255), `amount` decimal(10,2) NOT NULL, `currency` varchar(3) NOT NULL DEFAULT 'USD', `status` enum('pending','succeeded','failed','refunded') NOT NULL DEFAULT 'pending', `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `invoices` (`id` int AUTO_INCREMENT PRIMARY KEY, `userId` int NOT NULL, `paymentId` int NULL, `number` varchar(64) NOT NULL UNIQUE, `amount` decimal(10,2) NOT NULL, `status` enum('draft','issued','paid','void') NOT NULL DEFAULT 'issued', `issuedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `notifications` (`id` int AUTO_INCREMENT PRIMARY KEY, `userId` int NOT NULL, `type` varchar(64) NOT NULL, `title` varchar(255) NOT NULL, `body` text NULL, `readAt` timestamp NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `audit_logs` (`id` int AUTO_INCREMENT PRIMARY KEY, `userId` int NULL, `action` varchar(100) NOT NULL, `entityType` varchar(50), `entityId` varchar(100), `metadata` json, `requestId` varchar(64), `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO `plans` (`key`,`name`,`siteLimit`,`storageLimitMb`,`aiLimit`,`analyticsRetentionDays`,`customDomain`) VALUES ('starter','Starter',1,500,10,30,false),('pro','Pro',3,5000,50,180,true),('business','Business',10,25000,200,730,true) ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`siteLimit`=VALUES(`siteLimit`),`storageLimitMb`=VALUES(`storageLimitMb`),`aiLimit`=VALUES(`aiLimit`),`analyticsRetentionDays`=VALUES(`analyticsRetentionDays`),`customDomain`=VALUES(`customDomain`);
